package io.fireflysoftware.experience.finance.terminal.posting.impl;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import io.fireflysoftware.experience.finance.terminal.posting.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Mono;
class StaffPostingServiceTest {
    static final String TENANT=new UUID(0,1).toString(),BOOK=new UUID(0,2).toString(),ACTION=new UUID(0,3).toString(),DIGEST="a".repeat(64);
    byte[] body(String currency){return ("{\"expectedIntentDigest\":\""+DIGEST+"\",\"posting\":{\"actionId\":\""+ACTION+"\",\"source\":{\"owner\":\"LEDGER\",\"eventKind\":\"COMMIT\",\"revision\":1,\"effectOrdinal\":0},\"entries\":[{\"lines\":[{\"currency\":{\"isoCode\":\""+currency+"\"},\"postedScale\":2},{\"currency\":{\"isoCode\":\""+currency+"\"},\"postedScale\":2}]}]}}").getBytes(StandardCharsets.UTF_8);}
    StaffPostingResponse unknown(){return new StaffPostingResponse(UUID.fromString(ACTION),DIGEST,StaffPostingResponse.Status.OUTCOME_UNKNOWN,null,null,null);}
    @Test void completeOriginalWrapperAndActionAreCapturedBeforeCallerCanMutateInput(){var execution=mock(StaffPostingExecution.class);var seen=new AtomicReference<StaffPostingInvocation>();when(execution.execute(any())).thenAnswer(call->{seen.set(call.getArgument(0));return Mono.just(unknown());});byte[] bytes=body("USD");var result=new StaffPostingServiceImpl(execution).submit(TENANT,BOOK,bytes,false);Arrays.fill(bytes,(byte)'x');assertEquals(UUID.fromString(ACTION),result.block().actionId());assertTrue(seen.get().originalRequestJson().contains(ACTION));assertTrue(seen.get().originalRequestJson().contains(DIGEST));assertFalse(seen.get().recovery());verify(execution,times(1)).execute(any());}
    @Test void recoveryRetainsTheExactOriginalWrapperWithoutNewIdentity(){var execution=mock(StaffPostingExecution.class);var seen=new ArrayList<StaffPostingInvocation>();when(execution.execute(any())).thenAnswer(call->{seen.add(call.getArgument(0));return Mono.just(unknown());});var service=new StaffPostingServiceImpl(execution);service.submit(TENANT,BOOK,body("USD"),false).block();service.submit(TENANT,BOOK,body("USD"),true).block();assertEquals(seen.get(0).actionId(),seen.get(1).actionId());assertEquals(seen.get(0).originalRequestJson(),seen.get(1).originalRequestJson());assertTrue(seen.get(1).recovery());}
    @Test void unsupportedCurrencyCannotReachDomainDispatch(){var execution=mock(StaffPostingExecution.class);assertThrows(StaffPostingPreDispatchException.class,()->new StaffPostingServiceImpl(execution).submit(TENANT,BOOK,body("EUR"),false).block());verifyNoInteractions(execution);}
    @Test void duplicateUnknownFloatingAndNullFieldsCannotDisappearDuringCapture(){for(String variant:List.of("duplicate","unknown","floating","null")){var execution=mock(StaffPostingExecution.class);var raw=new String(body("USD"),StandardCharsets.UTF_8);raw=switch(variant){case"duplicate"->raw.replace("\"revision\":1","\"revision\":1,\"revision\":1");case"unknown"->raw.replace("\"actionId\":","\"claimedAdmission\":true,\"actionId\":");case"floating"->raw.replace("\"revision\":1","\"revision\":1.0");default->raw.replace("\"effectOrdinal\":0","\"effectOrdinal\":null");};var bytes=raw.getBytes(StandardCharsets.UTF_8);assertThrows(StaffPostingPreDispatchException.class,()->new StaffPostingServiceImpl(execution).submit(TENANT,BOOK,bytes,false).block());verifyNoInteractions(execution);}}
    @Test void absentExecutionCannotBecomeSuccessful(){var execution=mock(StaffPostingExecution.class);when(execution.execute(any())).thenReturn(Mono.empty());var value=new StaffPostingServiceImpl(execution).submit(TENANT,BOOK,body("USD"),false).block();assertEquals(StaffPostingResponse.Status.OUTCOME_UNKNOWN,value.status());assertEquals(UUID.fromString(ACTION),value.actionId());}
    @Test void unexpectedFailureRetainsOriginalIdentityAndNoRetry(){var execution=mock(StaffPostingExecution.class);when(execution.execute(any())).thenReturn(Mono.error(new IllegalStateException("controlled ambiguous delivery")));var value=new StaffPostingServiceImpl(execution).submit(TENANT,BOOK,body("USD"),false).block();assertEquals(StaffPostingResponse.Status.OUTCOME_UNKNOWN,value.status());assertEquals(DIGEST,value.intentDigest());verify(execution,times(1)).execute(any());}
    @Test void explicitPreDomainRefusalKeepsItsPhase(){var execution=mock(StaffPostingExecution.class);when(execution.execute(any())).thenReturn(Mono.error(new StaffPostingPreDispatchException(org.springframework.http.HttpStatus.FORBIDDEN)));var error=assertThrows(StaffPostingPreDispatchException.class,()->new StaffPostingServiceImpl(execution).submit(TENANT,BOOK,body("USD"),false).block());assertEquals(403,error.getStatusCode().value());}
    @Test void diagnosticsNeverRenderBearerOrCompleteFinancialPayload(){assertFalse(new StaffPostingCallerToken("aaa.bbb.ccc").toString().contains("aaa"));assertFalse(new StaffPostingInvocation(TENANT,BOOK,UUID.fromString(ACTION),DIGEST,"sensitive-complete-body",false).toString().contains("sensitive-complete-body"));}
}
